options.spec:
# The tracts' pseudo p-values (grey: all with neighbours; orange: the
# selection) and the significance cut. Folded as in PySAL (the smaller tail),
# so with no clustering they would spread evenly from 0 to 0.5; a pile at the
# left is the signal.
params:
  box: { select: crossfilter }
plot:
  - mark: rectY
    data: { from: clusters }
    x: { bin: p, steps: 40 }
    y: { count: }
    fill: 'rgba(128, 128, 128, 0.35)'
    inset: 0.5
  - mark: rectY
    data: { from: clusters, filterBy: $box }
    x: { bin: p, steps: 40 }
    y: { count: }
    fill: '#FF9830'
    inset: 0.5
  - mark: ruleX
    data: { from: clusters }
    x: { max: cut }
    stroke: '#e8423f'
    strokeWidth: 1.5
  - mark: text
    data: { from: clusters }
    x: { max: cut }
    text: { sql: "printf('p ≤ %.3g', max(cut))" }
    frameAnchor: top
    textAnchor: start
    dx: 4
    dy: 4
    fill: '#e8423f'
xDomain: [0, 0.5]
yScale: sqrt
xLabel: Pseudo p-value →
yLabel: ↑ Tracts
marginLeft: 44

# The group's share across the state's tracts (grey) and in the selection
# (orange). Brushing a range here selects the tracts in it, with the box.
params:
  box: { select: crossfilter }
plot:
  - mark: rectY
    data: { from: clusters }
    x: { bin: share, steps: 30 }
    y: { count: }
    fill: 'rgba(128, 128, 128, 0.35)'
    inset: 0.5
  - mark: rectY
    data: { from: clusters, filterBy: $box }
    x: { bin: share, steps: 30 }
    y: { count: }
    fill: '#FF9830'
    inset: 0.5
  - select: intervalX
    as: $box
    brush: { fillOpacity: 0.06, stroke: currentColor, strokeOpacity: 0.6 }
xDomain: Fixed
yScale: sqrt
xLabel: Share of residents (%) →
yLabel: ↑ Tracts
marginLeft: 44
